import {test,expect} from "@playwright/test";
import fs from "node:fs";
import {createHash} from "node:crypto";
const cases=JSON.parse(fs.readFileSync(new URL("../.cache/native-cases.json",import.meta.url),"utf8"));
const history=JSON.parse(fs.readFileSync(new URL("../web/example-history.json",import.meta.url),"utf8"));
const profile=JSON.parse(fs.readFileSync(new URL("../web/example-profile.json",import.meta.url),"utf8"));
async function ready(page){await page.goto("./");await expect(page.locator("#compare")).toBeEnabled();await expect(page.locator("#history")).not.toHaveValue("");await expect(page.locator("#profile")).not.toHaveValue("");}

test("actual worker repeats all native controls with exact input hashes",async({page})=>{
 test.setTimeout(90000);await ready(page);
 const outcomes=await page.evaluate(async(cases)=>{const worker=new Worker(new URL("worker.js",location.href),{type:"module"});await new Promise((resolve,reject)=>{worker.onmessage=({data})=>data.type==="ready"&&resolve();worker.onerror=reject;});let sequence=0;const run=text=>new Promise((resolve,reject)=>{const id=++sequence,timer=setTimeout(()=>reject(new Error("worker deadline")),10000);worker.onmessage=({data})=>{if(data.id!==id)return;clearTimeout(timer);if(data.type!=="result")reject(new Error(data.message));else resolve(data);};worker.postMessage({id,text});});const out=[];for(const c of cases){const a=await run(c.request),b=await run(c.request);if(a.report!==b.report)throw new Error("nonrepeatable output");out.push({request:c.request,response:JSON.parse(a.report),elapsedMs:a.elapsedMs});}worker.terminate();return out;},cases);
 const retained=outcomes.map(({request,response})=>({request,response}));fs.writeFileSync(".cache/wasm-cases.json",JSON.stringify(retained,null,2)+"\n");fs.writeFileSync(".cache/worker-timings.json",JSON.stringify(outcomes.map(({elapsedMs,response})=>({elapsedMs,kind:response.kind})),null,2)+"\n");expect(retained).toEqual(cases);
 const memory=await page.evaluate(async()=>{const m=await import("./pkg/lucia_history_inspector.js"),w=await m.default();const before=w.memory.buffer.byteLength;let refused=false;try{w.memory.grow(1024);}catch(e){refused=e instanceof RangeError;}return{before,after:w.memory.buffer.byteLength,refused};});expect(memory.refused).toBe(true);expect(memory.after).toBe(memory.before);expect(memory.after).toBeLessThanOrEqual(67108864);
 for(const c of retained.filter(c=>c.response.kind==="report")){const input=JSON.parse(c.request),r=c.response;expect(r.request_sha256).toBe(createHash("sha256").update(c.request).digest("hex"));expect(r.history_sha256).toBe(createHash("sha256").update(input.history_json).digest("hex"));if(r.profile_used)expect(r.profile_sha256).toBe(createHash("sha256").update(input.profile_json).digest("hex"));expect(r.counts.eras).toBe(r.interpreted_history.eras.length);expect(r.counts.persons).toBe(r.interpreted_history.eras.reduce((n,e)=>n+e.persons.length,0));expect(r.counts.events).toBe(r.interpreted_history.eras.reduce((n,e)=>n+e.events.length,0));}
});

test("native pass with warnings, empty coverage and unknown fields stays honest",async({page})=>{
 await ready(page);const h=structuredClone(history);h.extension={keep:"original only"};h.eras[0].events[0].actors=["unknown"];await page.locator("#history").fill(JSON.stringify(h));await page.locator("#compare").click();await expect(page.locator("#decision")).toContainText("comparison: pass");await expect(page.locator("#coverage")).toContainText("warnings: 1");await expect(page.locator("#findings")).toContainText("event_unknown_actor");await expect(page.locator("#projection-summary")).toContainText("1 history fields");let r=JSON.parse(await page.locator("#raw").textContent());expect(r.ignored_history_fields).toEqual(["extension"]);expect(r.interpreted_history.extension).toBeUndefined();expect(r.projection_notice).toContain("not a replacement");
 await page.locator("#history").fill(JSON.stringify({people_id:"empty",title:"Empty",worldview:"Synthetic"}));await page.locator("#profile").fill('{"profile_id":""}');await page.locator("#compare").click();await expect(page.locator("#decision")).toContainText("comparison: pass");await expect(page.locator("#profile-coverage")).toContainText("No required IDs");await expect(page.locator("#era-note")).toContainText("No era records");
 await page.locator("#profile").fill("{");await page.locator("#validate").click();await expect(page.locator("#decision")).toContainText("validation completed");await expect(page.locator("#profile-coverage")).toContainText("not used");await page.locator("#compare").click();await expect(page.locator("#status")).toContainText("invalid_profile_json");await expect(page.locator("#report")).toBeDisabled();await expect(page.locator("#history")).toHaveValue(JSON.stringify({people_id:"empty",title:"Empty",worldview:"Synthetic"}));
});

test("requirements, inert reference paths and exact request/report exports",async({page})=>{
 await ready(page);const h=structuredClone(history);h.title='<img src=x onerror="alert(1)">';h.eras[0].events[0].source_story_refs=[{path:"javascript:alert(1)",anchor:"<script>"}];const p=structuredClone(profile);p.required_event_ids=["absent"];await page.locator("#history").fill(JSON.stringify(h));await page.locator("#profile").fill(JSON.stringify(p));await page.locator("#compare").click();await expect(page.locator("#decision")).toContainText("hold");await expect(page.locator("#comparison")).toContainText("absent");await expect(page.locator("#events")).toContainText("javascript:alert(1)");await expect(page.locator("img")).toHaveCount(0);await expect(page.locator('a[href^="javascript:"]')).toHaveCount(0);
 const r=JSON.parse(await page.locator("#raw").textContent());let event=page.waitForEvent("download");await page.locator("#request").click();const request=JSON.parse(fs.readFileSync(await(await event).path(),"utf8"));expect(request.history_json).toBe(await page.locator("#history").inputValue());expect(request.profile_json).toBe(await page.locator("#profile").inputValue());event=page.waitForEvent("download");await page.locator("#report").click();expect(JSON.parse(fs.readFileSync(await(await event).path(),"utf8"))).toEqual(r);
 await page.locator("#profile").fill("{");await expect(page.locator("#report")).toBeDisabled();await expect(page.locator("#results")).toBeHidden();
});

test("both original files and independent delayed reads survive LF copy and mobile keyboard",async({page})=>{
 await page.addInitScript(()=>{const actual=File.prototype.arrayBuffer;File.prototype.arrayBuffer=function(){if(this.name.startsWith("slow-"))return new Promise(resolve=>setTimeout(()=>actual.call(this).then(resolve),250));return actual.call(this);};});await page.setViewportSize({width:390,height:844});await ready(page);
 const originals={history:Buffer.from("\ufeff"+JSON.stringify(history,null,2).replaceAll("\n","\r\n")),profile:Buffer.from("\ufeff"+JSON.stringify(profile,null,2).replaceAll("\n","\r\n"))};
 await page.locator("#history-file").setInputFiles({name:"slow-history.json",mimeType:"application/json",buffer:originals.history});await page.locator("#profile-file").setInputFiles({name:"slow-profile.json",mimeType:"application/json",buffer:originals.profile});
 for(const slot of ["history","profile"]){await expect(page.locator("#"+slot+"-original")).toBeEnabled();const event=page.waitForEvent("download");await page.locator("#"+slot+"-original").click();expect(fs.readFileSync(await(await event).path())).toEqual(originals[slot]);await page.locator("#"+slot+"-lf").click();expect((await page.locator("#"+slot).inputValue()).startsWith("\ufeff")).toBe(false);}
 await page.locator("#compare").focus();await page.locator("#compare").press("Enter");await expect(page.locator("#decision")).toContainText("comparison: pass");expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:".cache/mobile.png",fullPage:true});await page.setViewportSize({width:1280,height:900});await page.screenshot({path:".cache/desktop.png",fullPage:true});
});

test("unavailable WASM leaves independent model/build routes and editable inputs",async({page,request})=>{
 await page.route("**/*.wasm",route=>route.abort());await page.goto("./");await expect(page.locator("#status")).toContainText(/failed|unavailable/);await expect(page.locator("#history")).not.toHaveValue("");await expect(page.locator("#profile")).not.toHaveValue("");await expect(page.locator("#compare")).toBeDisabled();for(const name of ["Build instructions","Model details"]){const link=page.getByRole("link",{name,exact:true});expect((await request.get(await link.getAttribute("href"))).ok()).toBe(true);}
});
